    /// Appendix D selectTransitions, the half only this document can answer: the
    /// first of `state`'s own transitions, in document order, that `event` enables
    /// and whose guard holds. The engine walks the atomic states and their
    /// ancestors and keeps the ordered set; the null event asks for eventless
    /// transitions.
    public func firstEnabledTransition(
        _ state: RecordListState,
        event: RecordListEvent,
        engine: Engine<RecordListPolicy>
    ) -> EnabledTransition<RecordListState>? {
        switch state {
        case .open:
            if event == .recordListJoin {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [],
                        transitionIndex: 0,
                        hasActions: true,
                        isInternal: true
                    )
                }
            }
            if event == .recordListRoom {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [],
                        transitionIndex: 1,
                        hasActions: true,
                        isInternal: true
                    )
                }
            }
            if event == .recordListRole {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [],
                        transitionIndex: 2,
                        hasActions: true,
                        isInternal: true
                    )
                }
            }
            if event == .recordListEdit {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [],
                        transitionIndex: 3,
                        hasActions: true,
                        isInternal: true
                    )
                }
            }
            if event == .recordListClear {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [],
                        transitionIndex: 4,
                        hasActions: true,
                        isInternal: true
                    )
                }
            }
            if event == .recordListRetire {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [],
                        transitionIndex: 5,
                        hasActions: true,
                        isInternal: true
                    )
                }
            }
            if event == .recordListClose {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [],
                        transitionIndex: 6,
                        hasActions: true,
                        isInternal: true
                    )
                }
            }
            if event == .recordListTake {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [],
                        transitionIndex: 7,
                        hasActions: true,
                        isInternal: true
                    )
                }
            }
            if event == .recordListPass {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [],
                        transitionIndex: 8,
                        hasActions: true,
                        isInternal: true
                    )
                }
            }
            if event == .recordListWrite {
                // W3C SCXML 5.9: cond="floor > 0 && _event.data.wallTime <= floor" lowered to Swift at build time
                if (self.pendingPayloadTag == .recordListWrite && (self.vFloor > 0 && self.pendingRecordListWritePayload.wallTime <= self.vFloor)) {
                    return EnabledTransition(
                        source: state,
                        targets: [],
                        transitionIndex: 9,
                        hasActions: true,
                        isInternal: true
                    )
                }
            }
            if event == .recordListWrite {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [],
                        transitionIndex: 10,
                        hasActions: true,
                        isInternal: true
                    )
                }
            }
            if event == .recordListSupersede {
                // W3C SCXML 5.9: cond="floor > 0 && _event.data.parts > 1 && _event.data.atWallTime <= floor" lowered to Swift at build time
                if (self.pendingPayloadTag == .recordListSupersede && (self.vFloor > 0 && self.pendingRecordListSupersedePayload.parts > 1 && self.pendingRecordListSupersedePayload.atWallTime <= self.vFloor)) {
                    return EnabledTransition(
                        source: state,
                        targets: [],
                        transitionIndex: 11,
                        hasActions: true,
                        isInternal: true
                    )
